import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"Google Maps, routing & arrival APIs","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/maps-arrivals-setup.md","filePath":"integrations/maps-arrivals-setup.md"}'),i={name:"integrations/maps-arrivals-setup.md"};function s(l,e,n,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="google-maps-routing-arrival-apis" tabindex="-1">Google Maps, routing &amp; arrival APIs <a class="header-anchor" href="#google-maps-routing-arrival-apis" aria-label="Permalink to &quot;Google Maps, routing &amp; arrival APIs&quot;">​</a></h1><p>Source-reviewed v0.7.26. Default: disabled. The local geographic canvas remains available independently of licensed street maps.</p><h2 id="google-cloud-setup" tabindex="-1">Google Cloud setup <a class="header-anchor" href="#google-cloud-setup" aria-label="Permalink to &quot;Google Cloud setup&quot;">​</a></h2><ol><li>Create a dedicated Google Cloud project, attach approved billing, and create separate keys for the following functions. Restrict each to the necessary APIs and environment.</li><li>Enable Maps JavaScript API and create a map ID for the optional browser map. Restrict its browser key to exact approved HTTPS website origins. Set the following build-time variables only after approval:</li></ol><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>VITE_ENABLE_GOOGLE_FLEET_MAP</code></td><td>Optional map switch (default false)</td></tr><tr><td><code>VITE_GOOGLE_MAPS_BROWSER_KEY</code></td><td>Website- and API-restricted browser key</td></tr><tr><td><code>VITE_GOOGLE_MAPS_MAP_ID</code></td><td>Approved map ID</td></tr></tbody></table><ol start="3"><li>For operator location lookup, enable Places API (New) and Geocoding API. Configure server-only <code>TBPLUS_GOOGLE_LOCATION_SERVER_KEY</code> restricted to those APIs and server IP; <code>TBPLUS_ENABLE_GOOGLE_LOCATION_LOOKUP</code> remains false until approval. The initial reference lookup is Greece-only; it does not automatically persist provider addresses or override tariffs.</li><li>For road estimates, enable Routes API and use a separate IP- and API-restricted <code>TBPLUS_GOOGLE_ROUTES_SERVER_KEY</code>. Keep <code>TBPLUS_ENABLE_GOOGLE_ROUTES</code> false until accepted. Estimates are not guaranteed arrival times or prices. Pickup GPS freshness and authorization are checked; outbound and return legs are independent.</li><li>Configure cloud quotas and billing alerts (alerts are not hard spending caps). Test CSP, attribution, EEA terms, privacy disclosure, permission revocation, provider failure, GPS freshness and local fallback. Application request limits are not a replacement for cloud quota enforcement.</li></ol><h2 id="arrival-intelligence" tabindex="-1">Arrival intelligence <a class="header-anchor" href="#arrival-intelligence" aria-label="Permalink to &quot;Arrival intelligence&quot;">​</a></h2><p>v0.7.26 supports persistent transport identities, timestamped manual observations, advisory review and chauffeur briefs. Automated external flight/ferry monitoring, background polling, complete provider quota enforcement and licensed map activation remain outstanding. No approved flight/ferry API key names or live setup procedure are asserted. Review provider coverage, rights, freshness and costs before a future implementation. Arrival estimates must not automatically alter pickups or tariffs.</p><p>Official source-linked references: <a href="https://developers.google.com/maps/api-security-best-practices" target="_blank" rel="noreferrer">Maps API key security</a>, <a href="https://developers.google.com/maps/documentation/places/web-service/place-autocomplete" target="_blank" rel="noreferrer">Places autocomplete</a>, <a href="https://developers.google.com/maps/documentation/geocoding/guides-v3/requests-geocoding" target="_blank" rel="noreferrer">Geocoding</a>, <a href="https://developers.google.com/maps/documentation/routes/compute_route_directions" target="_blank" rel="noreferrer">Routes</a>.</p>',9)])])}const g=a(i,[["render",s]]);export{m as __pageData,g as default};
